    result = []
    for C, W, edges, weights in inputs:
        graph = [[] for _ in range(C + 1)]
        for x, y in edges:
            graph[x].append((y, weights[x - 1][y - 1]))
            graph[y].append((x, weights[x - 1][y - 1]))
        shortest_paths = [float('inf')] * (C + 1)
        shortest_paths[0] = 0
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > shortest_paths[u]:
                continue
            for v, weight in graph[u]:
                if shortest_paths[v] > d + weight:
                    shortest_paths[v] = d + weight
                    heapq.heappush(heap, (shortest_paths[v], v))
        result.append(max(shortest_paths))
    return result
